-- Two gaps closed in AL, the home of Arabic linguistic truth.
--
-- 1. Three indexes that existed only in kmaps-database (002_lx_content.sql), on tables and columns
--    still live. The other objects of 002 exist here under idx_arl_* names or sit on dropped tables;
--    007's balāgha tables are not ported — balāgha lives in km_quran, and nothing reads them.
CREATE INDEX IF NOT EXISTS idx_ar_ling_lem_pos  ON ar_ling_root_lemma(part_of_speech);
CREATE INDEX IF NOT EXISTS idx_ar_ling_lem_qrn  ON ar_ling_root_lemma(is_quran_word);
CREATE INDEX IF NOT EXISTS idx_ar_ling_exp_type ON ar_ling_root_lemma_tabir(expression_type_id);

-- 2. The kinds of badal (GT:badal_kind:*), authored into km_arabic's mirror on 2026-09-05 and never
--    into the registry, so scripts/project-gram-terms.mjs reported them as mirror-only. The registry
--    now holds them; the mirror keeps the same rows.
INSERT OR IGNORE INTO ar_ling_gram_category (category_key, name_ar, name_en, name_ur, discipline, applies_to, is_closed, display_order)
VALUES ('badal_kind', 'أنواع البدل', 'kinds of badal (substitute)', 'بدل کی اقسام', 'NH', 'both', 1, 311);

INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:badal', 'badal_kind', 'badal', NULL, 0, 'البدل', 'Badal (substitute)', 'بدل', 'تابعٌ مقصودٌ بالحكمِ بلا واسطة', 'A follower that is itself the target of the ruling, with no intervening particle', 'وہ تابع جو خود حکم کا مقصود ہو، بغیر کسی واسطے کے', 'التابعُ المقصودُ بالحكمِ بلا واسطةٍ بينه وبين متبوعه. والمبدلُ منه في حكم الطرح، والبدلُ هو المقصودُ بالحكم. وهو على نيةِ تكرارِ العامل.', 'The fourth of the tawabi. Ibn Hisham: tabi = genus covering all followers; maqsud bi-l-hukm excludes nat, tawkid and atf bayan; bila wasita excludes atf nasaq. The operator is understood as repeated.', 'توابع میں سے چوتھا۔ ابن ہشام کی حد: تابع (جنس)، مقصود بالحکم (نعت، تاکید، عطف بیان کو خارج کرتا ہے)، بلا واسطہ (عطف نسق کو خارج کرتا ہے)۔ عامل کا اعادہ مقدر ہوتا ہے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:mutabiq', 'badal_kind', 'mutabiq', 'GT:badal_kind:badal', 1, 'البدل المطابق (بدل كل من كل)', 'Badal mutabiq / kull min kull', 'بدلِ مطابق (بدل کل از کل)', 'الثاني عينُ الأول', 'The second is identical in reference to the first', 'دوسرا لفظ پہلے کا عین ہے', 'بدلُ الشيءِ مما كان طِبقَ معناه. ويُقال فيه أيضًا بدلُ شيءٍ من شيء لوجودِه فيما لا يُطلق عليه (كل).', 'Ibn Hisham writes badal kullin min kullin rather than al-kull min al-kull, to avoid the view that al- may not enter kull. Al-Suyuti prefers badal shay min shay where kull cannot be predicated, e.g. of the divine name.', 'ابن ہشام «بدل کلٍّ من کلٍّ» لکھتے ہیں۔ سیوطی «بدل شیءٍ من شیء» کو ترجیح دیتے ہیں جہاں «کل» کا اطلاق ممکن نہ ہو۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:badal_bad', 'badal_kind', 'badal_bad', 'GT:badal_kind:badal', 2, 'بدل بعض من كل', 'Badal ba d min kull (part from whole)', 'بدلِ بعض از کل', 'الثاني جزءٌ من الأول', 'The second is a part of the first', 'دوسرا لفظ پہلے کا جزو ہے', 'أن يكون الثاني جزءًا من الأول، قليلًا كان أو مساويًا للنصف أو أكثر. ولا بد من ضميرٍ رابط، مذكورًا أو مقدرًا.', 'Requires a linking pronoun, stated or estimated. Ibn Malik in Sharh al-Kafiya holds it is not strictly obligatory, though its presence is more common than its absence.', 'رابط ضمیر لازم ہے، مذکور ہو یا مقدر۔ ابن مالک شرحِ کافیہ میں اسے لازم نہیں مانتے، مگر وجود عدم سے زیادہ ہے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:ishtimal', 'badal_kind', 'ishtimal', 'GT:badal_kind:badal', 3, 'بدل الاشتمال', 'Badal al-ishtimal', 'بدلِ اشتمال', 'ملابسةٌ بغير الجزئية', 'A relation of involvement that is not part-whole', 'جزئیت کے بغیر تعلق', 'بدلُ الشيءِ مما يشتمل عليه، بشرط ألا يكون جزءًا منه. وفي المشتمِل خلاف: أهو الأولُ على الثاني، أم الثاني على الأول، أم العامل؟', 'Contested: al-Farisi and al-Rummani against al-Mubarrad, al-Sirafi, Ibn Jinni and Ibn al-Badhish, who locate the involvement in the amil — the thing actually stolen is the garment, not Zayd.', 'اشتمال کس میں ہے؟ اختلاف: فارسی و رمانی بمقابلہ مبرد، سیرافی، ابن جنی، ابن الباذش — جن کے نزدیک عامل میں ہے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:mubayin', 'badal_kind', 'mubayin', 'GT:badal_kind:badal', 4, 'البدل المباين', 'Badal mubayin (divergent)', 'بدلِ مباین', 'لا مطابقٌ ولا بعضٌ ولا مشتمَلٌ عليه', 'Neither identical, nor a part, nor involved', 'نہ مطابق، نہ بعض، نہ مشتمل', 'بدلُ الشيءِ مما يباينه. وهو ثلاثة أنواع: الغلط والنسيان والإضراب. ولا يقع بأقسامه في كلام البلغاء، ولذلك لم يقع في القرآن.', 'Al-Ghalayini: this class does not occur in the speech of the eloquent, which is why it is absent from the Quran. An eloquent speaker inserts bal to mark the retraction.', 'غلایینی: یہ قسم بلغاء کے کلام میں واقع نہیں ہوتی، اسی لیے قرآن میں نہیں۔ بلیغ «بل» لاتا ہے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:ghalat', 'badal_kind', 'ghalat', 'GT:badal_kind:mubayin', 1, 'بدل الغلط', 'Badal al-ghalat (slip of the tongue)', 'بدلِ غلط', 'يتعلق باللسان', 'Belongs to the tongue', 'زبان سے متعلق', 'ما ذُكر ليكون بدلًا من اللفظ الذي سبق إليه اللسان فذُكر غلطًا، نحو: جاء المعلمُ التلميذُ.', 'Al-Ghalayini distinguishes it from nisyan: ghalat belongs to the tongue (lisan), nisyan to the mind (janan).', 'غلایینی کا فرق: غلط کا تعلق لسان سے، نسیان کا جَنان سے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:nisyan', 'badal_kind', 'nisyan', 'GT:badal_kind:mubayin', 2, 'بدل النسيان', 'Badal al-nisyan (mistaken intent)', 'بدلِ نسیان', 'يتعلق بالجَنان', 'Belongs to the mind', 'دل و دماغ سے متعلق', 'ما ذُكر ليكون بدلًا من لفظٍ تبيّن بعد ذكره فسادُ قصده، نحو: سافر عليٌّ إلى دمشقَ بعلبكَّ.', 'The speaker intended the first word but then realised the intention itself was mistaken.', 'متکلم نے پہلا لفظ قصداً کہا، پھر معلوم ہوا کہ قصد ہی غلط تھا۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:idrab', 'badal_kind', 'idrab', 'GT:badal_kind:mubayin', 3, 'بدل الإضراب', 'Badal al-idrab (deliberate shift)', 'بدلِ اضراب', 'عدولٌ مقصودٌ عن الأول', 'A deliberate turning away from the first', 'پہلے سے قصداً عدول', 'ما كان قصدُ كلٍّ من البدل والمبدل منه فيه صحيحًا، غير أن المتكلم عدل عن قصد الأول إلى الثاني، نحو: خُذِ القلمَ الورقةَ.', 'Sibawayh at Kitab p.439: an yabduwa laka an tudriba an mururika bi-l-rajul. Both terms are valid; the speaker simply redirects.', 'سیبویہ، الکتاب ص٤٣٩۔ دونوں لفظ درست ہیں، متکلم صرف رخ بدلتا ہے۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:badal_mahall', 'badal_kind', 'badal_mahall', 'GT:badal_kind:badal', 5, 'البدل على المحل', 'Badal ala al-mahall', 'بدل علی المحل', 'يتبع الموضعَ لا اللفظ', 'Follows the syntactic position, not the surface case', 'ظاہری اعراب نہیں، محل کی پیروی', 'أن يُحمل البدلُ على محلِّ المبدل منه لا على لفظه، كالبدل من محل (لا) واسمها، ومن محل الجار والمجرور.', 'Sibawayh and Ibn Yaish devote chapters to it. Example: la ilaha illa HUWA, where huwa substitutes for the raf position of la with its noun.', 'سیبویہ اور ابن یعیش کے مستقل ابواب۔ مثال: لا إله إلا هو — «هو» لا اور اس کے اسم کے محلِ رفع سے بدل۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:taaddud', 'badal_kind', 'taaddud', 'GT:badal_kind:badal', 6, 'تعدّد البدل', 'Taaddud al-badal (multiple substitutes)', 'تعددِ بدل', 'عدة أبدال لمبدل منه واحد', 'Several substitutes for one substituted term', 'ایک مبدل منہ کے کئی بدل', 'أن يتعدد البدلُ مع اتحاد المبدل منه. قال أبو حيان: لا نصَّ عن أحدٍ من النحويين في جوازه أو منعه في بدل الكل والبعض والاشتمال. وظاهر كلام الخفاجي أن النحاة صرحوا بجوازه.', 'The pivot of al-Zamakhshari view that all six epithets in Ghafir 40:2-3 are abdal. Abu Hayyan refuses it for want of a nass; al-Khafaji answers that the grammarians did permit it.', 'غافر ٢-٣ میں زمخشری کے قول «سب ابدال ہیں» کا مدار۔ ابو حیان نص نہ ہونے پر انکار کرتے ہیں؛ خفاجی جواب دیتے ہیں۔', '#8C2F27', 'live', 'NH');
INSERT OR IGNORE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, name_ur, short_ar, short_en, short_ur, definition_ar, definition_en, definition_ur, badge_color, status, discipline) VALUES ('GT:badal_kind:tawti', 'badal_kind', 'tawti', 'GT:badal_kind:badal', 7, 'التوطئة والبساط', 'Al-tawti a wa-l-bisat (the mat)', 'توطئہ و بساط', 'الأولُ ممهِّدٌ لذكر الثاني', 'The first term is groundwork laid for the second', 'پہلا لفظ دوسرے کے لیے تمہید', 'قول ابن يعيش: صار الأولُ كالتوطئة والبساطِ لذكر الثاني. وهو الفارق الجوهري عن عطف البيان، إذ المقصود بالحديث فيه هو الأول.', 'Ibn Yaish, Sharh al-Mufassal p.275. The governing image for badal, and the discriminator against atf bayan.', 'ابن یعیش، شرح المفصل ص٢٧٥۔ بدل کی اصل تصویر، اور عطفِ بیان سے فرق کی کسوٹی۔', '#8C2F27', 'live', 'NH');
